const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const btn=t=>[...document.querySelectorAll('button,a,select option')].find(b=>b.textContent.trim()===t);
btn('50')?.click(); await sleep(300);
const seen=new Map();
for(let i=0;i<30;i++){
 document.querySelectorAll('table tbody tr').forEach(tr=>{const c=[...tr.cells].map(x=>x.textContent.trim());seen.set(c[0],c)});
 const n=btn('Next'); if(!n||n.disabled||n.getAttribute('aria-disabled')=='true')break; n.click(); await sleep(250);
}
let cnt=0,sum=0;for(const c of seen.values()){if(c[3]=='West'&&c[5]=='Refunded'){cnt++;sum+=parseFloat(c[6].replace(/[$,]/g,''))}}
[seen.size,cnt,sum.toFixed(2)]

